// Regenerates brands_gen.go from the TS runtimeBrands (the single source of the icons):
//   pnpm tsx smith/brands/generate.ts
import { writeFileSync } from "node:fs";
import path from "node:path";
import { runtimeBrands } from "../../packages/oar/src/brands.js";
import { morphBrand } from "../../packages/oar/src/community/morph/index.js";

const lines = [
  "// Code generated by smith/brands/generate.ts from packages/oar/src/brands.ts; DO NOT EDIT.",
  "",
  "package brands",
  "",
  'import "smith/oar"',
  "",
  "// Runtime is every built-in runtime's brand, by runtime id.",
  "var Runtime = map[string]oar.RuntimeBrand{",
];
for (const [id, brand] of Object.entries({ ...runtimeBrands, morph: morphBrand })) {
  const icons = "icons" in brand ? brand.icons : undefined;
  lines.push(`\t${JSON.stringify(id)}: {Name: ${JSON.stringify(brand.name)}, Icon: ${JSON.stringify(brand.icon)}, IconLight: ${JSON.stringify(icons?.light ?? "")}, IconDark: ${JSON.stringify(icons?.dark ?? "")}},`);
}
lines.push("}", "");
writeFileSync(path.join(import.meta.dirname, "brands_gen.go"), lines.join("\n"));
